from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
left_wheel = Motor(Port.A, Direction.COUNTERCLOCKWISE)
right_wheel = Motor(Port.E, Direction.CLOCKWISE)
front_motor = Motor(Port.D, Direction.CLOCKWISE)
rear_motor = Motor(Port.C, Direction.CLOCKWISE)
left_color_sensor = ColorSensor(Port.B)
right_color_sensor = ColorSensor(Port.F)
WHEEL_DIAMETER = 88
WHEEL_TRACK = 144
PIVOT_RADIUS = WHEEL_TRACK / 2
LEFT_PIVOT = WHEEL_TRACK / -2
RIGHT_PIVOT = WHEEL_TRACK / 2
ADB_GEAR_RATIO = (36 / 28) * (20 / 12)
drive_base = DriveBase(left_wheel, right_wheel, WHEEL_DIAMETER, WHEEL_TRACK)


